import React, { useState, useEffect } from 'react';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '../ui/dialog';
import { Button } from '../ui/button';
import { Badge } from '../ui/badge';
import { Avatar, AvatarFallback } from '../ui/avatar';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '../ui/select';
import { UserPlus, X, Crown, User as UserIcon, Eye, Trash2 } from 'lucide-react';
import { clientTeamService } from '../../services/clientTeamService';
import Swal from 'sweetalert2';

export const AssignConsultantModal = ({ isOpen, onClose, client, onSuccess }) => {
  const [availableConsultants, setAvailableConsultants] = useState([]);
  const [assignedConsultants, setAssignedConsultants] = useState([]);
  const [selectedConsultant, setSelectedConsultant] = useState('');
  const [selectedRole, setSelectedRole] = useState('member');
  const [loading, setLoading] = useState(false);
  const [loadingData, setLoadingData] = useState(true);

  useEffect(() => {
    if (isOpen && client) {
      loadData();
    }
  }, [isOpen, client]);

  const loadData = async () => {
    try {
      setLoadingData(true);
      const [consultants, assignments] = await Promise.all([
        clientTeamService.getAvailableConsultants(),
        clientTeamService.getClientConsultants(client._id),
      ]);

      setAvailableConsultants(consultants);
      setAssignedConsultants(assignments);
    } catch (error) {
      console.error('Error loading data:', error);
      Swal.fire({
        icon: 'error',
        title: 'Error',
        text: 'No se pudo cargar la información',
        confirmButtonColor: '#dc2626',
      });
    } finally {
      setLoadingData(false);
    }
  };

  const handleAssign = async () => {
    if (!selectedConsultant) {
      Swal.fire({
        icon: 'warning',
        title: 'Selecciona un Consultor',
        text: 'Por favor selecciona un consultor antes de continuar',
        confirmButtonColor: '#16a34a',
      });
      return;
    }

    setLoading(true);
    try {
      await clientTeamService.assignConsultant({
        client_id: client._id,
        user_id: selectedConsultant,
        role: selectedRole,
      });

      Swal.fire({
        icon: 'success',
        title: '✅ Consultor Asignado',
        toast: true,
        position: 'top-end',
        showConfirmButton: false,
        timer: 2000,
        timerProgressBar: true,
      });

      setSelectedConsultant('');
      setSelectedRole('member');
      await loadData();
      onSuccess?.();
    } catch (error) {
      Swal.fire({
        icon: 'error',
        title: 'Error',
        text: error.response?.data?.detail || 'No se pudo asignar el consultor',
        confirmButtonColor: '#dc2626',
      });
    } finally {
      setLoading(false);
    }
  };

  const handleRemoveAssignment = async (assignmentId, consultantName) => {
    const result = await Swal.fire({
      title: '¿Remover Asignación?',
      html: `Se quitará a <strong>${consultantName}</strong> de este cliente`,
      icon: 'warning',
      showCancelButton: true,
      confirmButtonColor: '#dc2626',
      cancelButtonColor: '#6b7280',
      confirmButtonText: 'Sí, remover',
      cancelButtonText: 'Cancelar',
    });

    if (result.isConfirmed) {
      try {
        await clientTeamService.removeAssignment(assignmentId);
        
        Swal.fire({
          icon: 'success',
          title: 'Asignación Removida',
          toast: true,
          position: 'top-end',
          showConfirmButton: false,
          timer: 2000,
        });

        await loadData();
        onSuccess?.();
      } catch (error) {
        Swal.fire({
          icon: 'error',
          title: 'Error',
          text: 'No se pudo remover la asignación',
          confirmButtonColor: '#dc2626',
        });
      }
    }
  };

  const getRoleIcon = (role) => {
    switch (role) {
      case 'lead':
        return <Crown className="w-4 h-4 text-yellow-600" />;
      case 'member':
        return <UserIcon className="w-4 h-4 text-blue-600" />;
      case 'viewer':
        return <Eye className="w-4 h-4 text-gray-600" />;
      default:
        return <UserIcon className="w-4 h-4" />;
    }
  };

  const getRoleLabel = (role) => {
    const labels = {
      lead: 'Líder',
      member: 'Miembro',
      viewer: 'Observador',
    };
    return labels[role] || role;
  };

  const getRoleColor = (role) => {
    const colors = {
      lead: 'bg-yellow-100 text-yellow-700 border-yellow-300',
      member: 'bg-blue-100 text-blue-700 border-blue-300',
      viewer: 'bg-gray-100 text-gray-700 border-gray-300',
    };
    return colors[role] || colors.member;
  };

  if (!client) return null;

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="sm:max-w-[600px] max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>Asignar Consultores - {client.company_name}</DialogTitle>
        </DialogHeader>

        {loadingData ? (
          <div className="flex items-center justify-center py-8">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-green-500"></div>
          </div>
        ) : (
          <>
            {/* Formulario de Asignación */}
            <div className="space-y-4 py-4 border-b">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="text-sm font-medium mb-2 block">
                    Consultor *
                  </label>
                  <Select value={selectedConsultant} onValueChange={setSelectedConsultant}>
                    <SelectTrigger>
                      <SelectValue placeholder="Seleccionar consultor..." />
                    </SelectTrigger>
                    <SelectContent>
                      {availableConsultants
                        .filter(c => !assignedConsultants.some(a => a.user_id._id === c._id))
                        .map((consultant) => (
                          <SelectItem key={consultant._id} value={consultant._id}>
                            {consultant.full_name} ({consultant.email})
                          </SelectItem>
                        ))}
                    </SelectContent>
                  </Select>
                </div>

                <div>
                  <label className="text-sm font-medium mb-2 block">Rol *</label>
                  <Select value={selectedRole} onValueChange={setSelectedRole}>
                    <SelectTrigger>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="lead">
                        <div className="flex items-center gap-2">
                          <Crown className="w-4 h-4 text-yellow-600" />
                          Líder
                        </div>
                      </SelectItem>
                      <SelectItem value="member">
                        <div className="flex items-center gap-2">
                          <UserIcon className="w-4 h-4 text-blue-600" />
                          Miembro
                        </div>
                      </SelectItem>
                      <SelectItem value="viewer">
                        <div className="flex items-center gap-2">
                          <Eye className="w-4 h-4 text-gray-600" />
                          Observador
                        </div>
                      </SelectItem>
                    </SelectContent>
                  </Select>
                </div>
              </div>

              <Button
                onClick={handleAssign}
                disabled={loading || !selectedConsultant}
                className="w-full bg-green-600 hover:bg-green-700"
              >
                <UserPlus className="w-4 h-4 mr-2" />
                {loading ? 'Asignando...' : 'Asignar Consultor'}
              </Button>
            </div>

            {/* Lista de Consultores Asignados */}
            <div className="space-y-3 py-4">
              <h4 className="font-semibold text-gray-900">
                Consultores Asignados ({assignedConsultants.length})
              </h4>

              {assignedConsultants.length === 0 ? (
                <div className="text-center py-8 bg-gray-50 rounded-lg">
                  <UserIcon className="w-12 h-12 mx-auto text-gray-400 mb-2" />
                  <p className="text-gray-600 text-sm">
                    No hay consultores asignados
                  </p>
                </div>
              ) : (
                <div className="space-y-2 max-h-[300px] overflow-y-auto">
                  {assignedConsultants.map((assignment) => (
                    <div
                      key={assignment._id}
                      className="flex items-center justify-between p-3 bg-gray-50 rounded-lg hover:bg-gray-100 transition-colors"
                    >
                      <div className="flex items-center gap-3 flex-1">
                        <Avatar className="h-10 w-10">
                          <AvatarFallback className="bg-green-100 text-green-700 text-sm font-semibold">
                            {assignment.user_id.full_name
                              ?.split(' ')
                              .map((n) => n[0])
                              .join('')
                              .toUpperCase()}
                          </AvatarFallback>
                        </Avatar>

                        <div className="flex-1 min-w-0">
                          <p className="font-semibold text-gray-900 truncate">
                            {assignment.user_id.full_name}
                          </p>
                          <p className="text-xs text-gray-500 truncate">
                            {assignment.user_id.email}
                          </p>
                        </div>

                        <Badge className={`border ${getRoleColor(assignment.role)}`}>
                          <div className="flex items-center gap-1">
                            {getRoleIcon(assignment.role)}
                            <span>{getRoleLabel(assignment.role)}</span>
                          </div>
                        </Badge>
                      </div>

                      <Button
                        onClick={() =>
                          handleRemoveAssignment(
                            assignment._id,
                            assignment.user_id.full_name
                          )
                        }
                        variant="ghost"
                        size="sm"
                        className="ml-2 text-red-600 hover:text-red-700 hover:bg-red-50"
                      >
                        <Trash2 className="w-4 h-4" />
                      </Button>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </>
        )}

        <DialogFooter>
          <Button variant="outline" onClick={onClose}>
            Cerrar
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};
